// @FIGURE_CODE_BEGIN
var tlDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var TLW = 1240, TLH = 650;
tlDraw.viewbox(0, 0, TLW, TLH);

var BLUE = '#2196c4', MAG = '#a0459b', MAGD = '#8e2f8a', GRAYA = '#cdcdcd', INK = '#1a1a1a';
var SERIF = 'Georgia, "Times New Roman", serif';

function tlUnit(dx, dy) { var L = Math.hypot(dx, dy) || 1; return { x: dx / L, y: dy / L }; }
function tlFmt(m) { if (!isFinite(m) || Math.abs(m) > 99) return '±∞'; return (Math.round(m * 1000) / 1000).toFixed(3); }

/* ── panel definitions ─────────────────────────────────────────────── */
var A = {
  id: 'a',
  rect: { x0: 26, y0: 35, x1: 500, y1: 552 },
  Rw: 230, Rarc: 210, unitScale: 85,
  ox: 110, oy: 560, sc: 85,
  xOf: function (t) { return -0.6 + 4.5 * t; },
  f: function (x) { return 1.2 + 2.0 * x - 0.14 * x * x * x; },
  fp: function (x) { return 2.0 - 0.42 * x * x; },
  pt: function (t) { var x = this.xOf(t); return { x: this.ox + x * this.sc, y: this.oy - this.f(x) * this.sc }; },
  tP: function (p) { return Math.min(0.86, Math.max(0, 0.05 + 1.03 * p)); },
  P: function (p) { return this.pt(this.tP(p)); },
  Q: function (p, q) { var tp = this.tP(p); return this.pt(tp + q * (0.90 - tp)); },
  tan: function (p) { var x = this.xOf(this.tP(p)); return tlUnit(1, -this.fp(x)); }
};

var B = {
  id: 'b',
  rect: { x0: 665, y0: 35, x1: 1135, y1: 600 },
  Rw: 200, Rarc: 195, unitScale: 140,
  cx: 935, cy: 390, R: 140,
  ang: function (p) { return 160 - 60 * p; },
  ptA: function (a) { var r = a * Math.PI / 180; return { x: this.cx + this.R * Math.cos(r), y: this.cy - this.R * Math.sin(r) }; },
  P: function (p) { return this.ptA(this.ang(p)); },
  Q: function (p, q) { return this.ptA(this.ang(p) - 120 * q); },
  tan: function (p) { var r = this.ang(p) * Math.PI / 180; return { x: Math.sin(r), y: Math.cos(r) }; }
};

/* ── layer order ───────────────────────────────────────────────────── */
var gBG = tlDraw.group();
var gAxes = tlDraw.group();
A.gLines = tlDraw.group(); A.gCurve = tlDraw.group(); A.gMarks = tlDraw.group();
B.gLines = tlDraw.group(); B.gCurve = tlDraw.group(); B.gMarks = tlDraw.group();
var gText = tlDraw.group();

A.grad = tlDraw.gradient('radial', function (add) {
  add.stop(0, '#a8459f', 0.55); add.stop(0.35, '#c47cbe', 0.40); add.stop(1, '#ffffff', 0.02);
});
B.grad = tlDraw.gradient('radial', function (add) {
  add.stop(0, '#a8459f', 0.55); add.stop(0.35, '#c47cbe', 0.40); add.stop(1, '#ffffff', 0.02);
});

/* active-panel hint (very subtle) */
var bgA = gBG.rect(590, 624).move(12, 16).radius(14).fill('#f2f7fb').opacity(0);
var bgB = gBG.rect(590, 624).move(640, 16).radius(14).fill('#f2f7fb').opacity(0);

/* ── axes (panel a) ────────────────────────────────────────────────── */
gAxes.line(35, 560, 488, 560).stroke({ color: INK, width: 2.6, linecap: 'round' });
gAxes.polygon('502,560 486,553 486,567').fill(INK);
gAxes.line(52, 590, 52, 34).stroke({ color: INK, width: 2.6, linecap: 'round' });
gAxes.polygon('52,20 45,36 59,36').fill(INK);

/* ── static curves ─────────────────────────────────────────────────── */
(function () {
  var pts = [];
  for (var i = 0; i <= 90; i++) { var p = A.pt(i / 90); pts.push(p.x + ',' + p.y); }
  var cv = A.gCurve.polyline(pts.join(' ')).fill('none')
    .stroke({ color: BLUE, width: 4.5, linecap: 'round', linejoin: 'round' });
  cv.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('A smooth curve — the tangent direction changes from point to point.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('The curve', 'Every point of this smooth curve has its own tangent direction. Move P with the slider to see the limiting line change: the tangent is a local object, determined by the curve near P only.'); });
})();
(function () {
  var c = B.gCurve.circle(2 * B.R).center(B.cx, B.cy).fill('none').stroke({ color: BLUE, width: 4.5 });
  c.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('A circle — the classical tangent touches it at exactly one point.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('The circle', 'For a circle the limiting line of the secants touches the circle at P only and is perpendicular to the radius OP. The limit definition therefore reproduces the classical geometric tangent.'); });
})();

/* ── static text labels ────────────────────────────────────────────── */
function tlLabel(x, y, str, size, italic, anchor) {
  var t = gText.text(str);
  t.font({ family: SERIF, size: size, anchor: anchor || 'start', style: italic ? 'italic' : 'normal' });
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
  t.fill(INK);
  t.move(x, y);
  return t;
}
function tlCenter(cx, cy, str, size, italic) {
  var t = tlLabel(0, 0, str, size, italic, 'middle');
  t.center(cx, cy);
  return t;
}
tlLabel(76, 126, 'Tangent', 25, false);
tlLabel(76, 158, 'line', 25, false);
tlLabel(506, 392, 'Secant', 25, false);
tlLabel(506, 424, 'line', 25, false);
tlLabel(700, 66, 'Tangent', 25, false);
tlLabel(700, 98, 'line', 25, false);
tlLabel(1146, 272, 'Secant', 24, false);
tlLabel(1146, 304, 'line', 24, false);
tlCenter(472, 536, 'x', 26, true);
tlCenter(74, 46, 'y', 26, true);
tlCenter(270, 628, '(a)', 26, true);
tlCenter(940, 628, '(b)', 26, true);

/* ── geometry helpers ──────────────────────────────────────────────── */
function clipLine(P, d, r) {
  var t0 = -1e7, t1 = 1e7, ok = true;
  function upd(p, q) {
    if (Math.abs(p) < 1e-9) { if (q < 0) ok = false; return; }
    var t = q / p;
    if (p < 0) { if (t > t1) { ok = false; return; } if (t > t0) t0 = t; }
    else { if (t < t0) { ok = false; return; } if (t < t1) t1 = t; }
  }
  upd(-d.x, P.x - r.x0); if (!ok) return null;
  upd(d.x, r.x1 - P.x); if (!ok) return null;
  upd(-d.y, P.y - r.y0); if (!ok) return null;
  upd(d.y, r.y1 - P.y); if (!ok) return null;
  return [{ x: P.x + t0 * d.x, y: P.y + t0 * d.y }, { x: P.x + t1 * d.x, y: P.y + t1 * d.y }];
}

function drawWedge(pn, P, T, dS) {
  pn.grad.attr({ gradientUnits: 'userSpaceOnUse', cx: P.x, cy: P.y, fx: P.x, fy: P.y, r: pn.Rw });
  var mid = tlUnit(T.x + dS.x, T.y + dS.y);
  var R = pn.Rw;
  var pts = [
    P.x + ',' + P.y,
    (P.x + T.x * R) + ',' + (P.y + T.y * R),
    (P.x + mid.x * R) + ',' + (P.y + mid.y * R),
    (P.x + dS.x * R) + ',' + (P.y + dS.y * R)
  ].join(' ');
  pn.gLines.polygon(pts).attr('fill', pn.grad.url()).stroke('none');
}

function drawSweep(pn, P, d0, d1) {
  var a0 = Math.atan2(-d0.y, d0.x), a1 = Math.atan2(-d1.y, d1.x);
  while (a1 < a0) a1 += 2 * Math.PI;
  if (a1 - a0 < 0.14) return;
  var R = pn.Rarc, headLen = 27, headHalf = 12;
  var aEnd = a1 - (headLen * 0.8) / R;
  if (aEnd <= a0) return;
  var S = { x: P.x + R * Math.cos(a0), y: P.y - R * Math.sin(a0) };
  var E = { x: P.x + R * Math.cos(aEnd), y: P.y - R * Math.sin(aEnd) };
  var large = (aEnd - a0) > Math.PI ? 1 : 0;
  pn.gLines.path('M' + S.x + ',' + S.y + ' A' + R + ',' + R + ' 0 ' + large + ' 0 ' + E.x + ',' + E.y)
    .fill('none').stroke({ color: GRAYA, width: 2.4, linecap: 'round' });
  var u = { x: -Math.sin(a1), y: -Math.cos(a1) };
  var tipBase = { x: P.x + R * Math.cos(a1), y: P.y - R * Math.sin(a1) };
  var tip = { x: tipBase.x + u.x * 4, y: tipBase.y + u.y * 4 };
  var bs = { x: tip.x - u.x * headLen, y: tip.y - u.y * headLen };
  var n = { x: -u.y, y: u.x };
  var poly = [
    tip.x + ',' + tip.y,
    (bs.x + n.x * headHalf) + ',' + (bs.y + n.y * headHalf),
    (bs.x - n.x * headHalf) + ',' + (bs.y - n.y * headHalf)
  ].join(' ');
  pn.gLines.polygon(poly).fill('#f6f6f6').stroke({ color: '#c2c2c2', width: 1.8, linejoin: 'round' });
}

function dotLabel(g, x, y, str) {
  var t = g.text(str);
  t.font({ family: SERIF, size: 26, style: 'italic', anchor: 'middle' });
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
  t.fill(INK);
  t.center(x, y);
  return t;
}

/* ── panel rendering ───────────────────────────────────────────────── */
function renderPanel(pn, s) {
  pn.gLines.clear(); pn.gMarks.clear();
  var P = pn.P(s.p), T = pn.tan(s.p);
  var qs = [];
  if (s.fan) { [1, 0.5, 0.22].forEach(function (g) { if (Math.abs(g - s.q) > 0.05) qs.push(g); }); }
  qs.push(s.q);
  qs.sort(function (a, b) { return b - a; });

  function info(qq) {
    var Q = pn.Q(s.p, qq);
    return { q: qq, Q: Q, d: tlUnit(Q.x - P.x, Q.y - P.y), m: -(Q.y - P.y) / ((Q.x - P.x) || 1e-9) };
  }
  var steep = info(qs[qs.length - 1]);
  var shallow = info(qs[0]);

  drawWedge(pn, P, T, steep.d);
  drawSweep(pn, P, shallow.d, T);

  qs.forEach(function (qq) {
    var o = info(qq), cur = (qq === s.q);
    var seg = clipLine(P, o.d, pn.rect);
    if (!seg) return;
    pn.gLines.line(seg[0].x, seg[0].y, seg[1].x, seg[1].y)
      .stroke({ color: MAG, width: cur ? 3 : 1.8, opacity: cur ? 1 : 0.40, linecap: 'round' });
    if (cur) {
      var hit = pn.gMarks.line(seg[0].x, seg[0].y, seg[1].x, seg[1].y)
        .stroke({ color: '#000', width: 16, opacity: 0 });
      hit.css('cursor', 'pointer')
        .on('mousemove', function (e) { showTooltip('Secant through P and Q  —  slope m_PQ = ' + tlFmt(o.m), e); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('Secant line', 'A secant cuts the curve at two distinct points, P and Q. Its slope is the average rate of change of the curve between them. As Q slides toward P the secant pivots about P and its slope approaches a single number.');
        });
    }
  });

  var segT = clipLine(P, T, pn.rect);
  if (segT) {
    pn.gLines.line(segT[0].x, segT[0].y, segT[1].x, segT[1].y)
      .stroke({ color: MAGD, width: 4, linecap: 'round' });
    var hitT = pn.gMarks.line(segT[0].x, segT[0].y, segT[1].x, segT[1].y)
      .stroke({ color: '#000', width: 16, opacity: 0 });
    hitT.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Tangent line at P  —  slope = ' + tlFmt(-T.y / (T.x || 1e-9)), e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Tangent line', 'The tangent at P is defined as the limiting position of the secant lines PQ as Q approaches P. The secant through P and Q does not exist when Q = P, yet the secant slopes still converge — that limit is the tangent slope.');
      });
  }

  qs.forEach(function (qq) {
    var o = info(qq), cur = (qq === s.q);
    var dot = pn.gMarks.circle(cur ? 15 : 11).center(o.Q.x, o.Q.y)
      .fill(BLUE).stroke({ color: '#ffffff', width: cur ? 2 : 1.5 });
    if (cur) {
      dot.css('cursor', 'pointer')
        .on('mousemove', function (e) { showTooltip('Q — the moving point (slide it toward P)', e); })
        .on('mouseleave', hideTooltip)
        .on('click', function () { showPopup('The point Q', 'Q is the roving second point. Everything interesting happens in the limit Q → P: the secant never disappears, it settles onto the tangent.'); });
    }
  });

  var Pd = pn.gMarks.circle(15).center(P.x, P.y).fill(BLUE).stroke({ color: '#ffffff', width: 2 });
  Pd.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('P — the fixed point of tangency', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('The point P', 'P stays put while Q slides. Every secant is pinned at P, so the whole family pivots about this single point and collapses onto the tangent there.'); });

  var Qc = pn.Q(s.p, s.q);
  if (pn.id === 'a') {
    dotLabel(pn.gMarks, P.x - 26, P.y - 12, 'P');
    dotLabel(pn.gMarks, Qc.x + 2, Qc.y + 30, 'Q');
  } else {
    dotLabel(pn.gMarks, P.x - 28, P.y - 8, 'P');
    dotLabel(pn.gMarks, Qc.x - 4, Qc.y + 32, 'Q');
  }
}

/* ── state & rendering ─────────────────────────────────────────────── */
var tlState = { panel: 'a', q: 1, p: 0.2, fan: true };

function tlRender() {
  renderPanel(A, tlState.panel === 'a' ? { p: tlState.p, q: tlState.q, fan: tlState.fan } : { p: 0.2, q: 1, fan: true });
  renderPanel(B, tlState.panel === 'b' ? { p: tlState.p, q: tlState.q, fan: tlState.fan } : { p: 0.35, q: 1, fan: true });
  bgA.opacity(tlState.panel === 'a' ? 0.75 : 0);
  bgB.opacity(tlState.panel === 'b' ? 0.75 : 0);
  var pn = tlState.panel === 'a' ? A : B;
  var P = pn.P(tlState.p), Q = pn.Q(tlState.p, tlState.q), T = pn.tan(tlState.p);
  var ms = -(Q.y - P.y) / ((Q.x - P.x) || 1e-9);
  var mt = -T.y / (T.x || 1e-9);
  var d = Math.hypot(Q.x - P.x, Q.y - P.y) / pn.unitScale;
  document.getElementById('mSecOut').textContent = tlFmt(ms);
  document.getElementById('mTanOut').textContent = tlFmt(mt);
  document.getElementById('dPQOut').textContent = d.toFixed(3);
}

/* ── control handlers ──────────────────────────────────────────────── */
function update_qPosition(v) { tlState.q = v; tlRender(); }
function update_pPosition(v) { tlState.p = v; tlRender(); }
function toggle_showFan(on) { tlState.fan = !!on; tlRender(); }
function toggle_panel(on) { tlState.panel = on ? 'b' : 'a'; tlRender(); }

/* ── demo step player ──────────────────────────────────────────────── */
var tlSteps = [
  {
    title: 'A far-away secant',
    narration: 'Q sits well to the right of P on the blue curve; the pink line through P and Q is a secant, cutting the curve at two clearly separate points. Its slope is the average rate of change between P and Q.',
    state: { panel: 'a', qPosition: 1, pPosition: 0.2, showFan: true }
  },
  {
    title: 'Sliding Q toward P',
    narration: 'Drag Q closer to P and the secant pivots about P, steepening as the slope readout climbs. Each intermediate position leaves a ghost secant, building the pink fan.',
    state: { panel: 'a', qPosition: 0.45, pPosition: 0.2, showFan: true }
  },
  {
    title: 'The limiting position',
    narration: 'With Q almost on top of P the secants have collapsed onto one line — the tangent. The slope readout has settled on a definite limiting value even though Q never actually reaches P.',
    state: { panel: 'a', qPosition: 0.03, pPosition: 0.2, showFan: true }
  },
  {
    title: 'The tangent is local',
    narration: 'Move P to the crest of the curve and repeat: the limiting line is now horizontal (slope 0). The tangent direction depends on where on the curve you stand.',
    state: { panel: 'a', qPosition: 0.05, pPosition: 0.55, showFan: true }
  },
  {
    title: 'Does it match the circle?',
    narration: 'Switch to the circle and run the same construction. The limiting line touches the circle at P only and is perpendicular to the radius — the new definition agrees with the classical geometric tangent.',
    state: { panel: 'b', qPosition: 0.04, pPosition: 0.35, showFan: true }
  }
];
var tlStep = 0;

function applyStep(i) {
  tlStep = ((i % tlSteps.length) + tlSteps.length) % tlSteps.length;
  var s = tlSteps[tlStep].state;
  var pi = document.getElementById('panelInput');
  pi.checked = (s.panel === 'b');
  tlState.panel = s.panel;
  var qi = document.getElementById('qPositionInput');
  qi.value = s.qPosition; document.getElementById('qPositionVal').value = s.qPosition; tlState.q = +s.qPosition;
  var ppi = document.getElementById('pPositionInput');
  ppi.value = s.pPosition; document.getElementById('pPositionVal').value = s.pPosition; tlState.p = +s.pPosition;
  var fi = document.getElementById('showFanInput');
  fi.checked = !!s.showFan; tlState.fan = !!s.showFan;
  document.getElementById('stepTitle').textContent = 'Step ' + (tlStep + 1) + ' — ' + tlSteps[tlStep].title;
  document.getElementById('demoNarration').textContent = tlSteps[tlStep].narration;
  document.getElementById('stepLabel').textContent = (tlStep + 1) + ' / ' + tlSteps.length;
  tlRender();
}
function nextStep() { applyStep(tlStep + 1); }
function prevStep() { applyStep(tlStep - 1); }

applyStep(0);
window.__markRendered();
